import{_ as t,o as p,c as o,a5 as n}from"./chunks/framework.BvXk9IVy.js";const c=JSON.parse('{"title":"《雪中悍刀行》读后记","description":"","frontmatter":{"title":"《雪中悍刀行》读后记"},"headers":[],"relativePath":"novels/xuezhong.md","filePath":"novels/xuezhong.md","lastUpdated":1791895356000}'),a={name:"novels/xuezhong.md"};function d(s,e,i,r,_,h){return p(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="《雪中悍刀行》读后记" tabindex="-1">《雪中悍刀行》读后记</h1><blockquote><p>江湖是一张珠帘，有人掀帘而入，有人帘外立雪。</p></blockquote><p>这本书的字数一直在劝退人，我拖了很久才翻开。真正读进去之后才发现，它吸引我的地方和武侠几乎没关系——刀光当然好看，但留住我的是那些活在刀光边上的人。</p><h2 id="配角各有各的活法" tabindex="-1">配角各有各的活法</h2><p>徐凤年是主角，可这本书里写得最好的，往往不是他。</p><p>作者的写法是：<strong>每个人都当成主角来写</strong>。哪怕只出场一场戏，也要给他一个来处、一个放不下的东西，还有一句只属于他自己的话。所以那些小人物不是用来推动情节的，他们有自己的人生轨迹，主角路过时，他们正好在那里而已。</p><p>有人一辈子没什么出息，最后做了一件对得起自己的事就走了；有人守着一间铺子、一坛酒、一句承诺过日子。江湖在这本书里不是擂台，是一堆人各自的营生。</p><h2 id="那点烟火气" tabindex="-1">那点烟火气</h2><p>书里大段大段的篇幅用在吃饭、赶路、闲聊和打盹上。严格说来这些都可以删，删完节奏会紧凑得多。</p><p>但我猜作者是故意的。正因为有这些慢下来的段落，那些突然而至的死别才有份量——一个你看着他抱怨过饭菜难吃、抱怨过赶路太累的人，忽然就不在了，那种感觉和看一个纯粹的功能性角色退场完全不同。</p><p>雪中喝过的酒、下过的面、剥过的花生，都是用来给这些人做底子的。</p><h2 id="中段确实慢" tabindex="-1">中段确实慢</h2><p>公平地讲，中段拖。人物越铺越多，线索越岔越远，主角常常半天不出现，读着有点走神。</p><p>我没跳，是因为那种慢有它的脾气。像站在一场庙会里，主角只是其中一个方向，更多时候是身边不断有人说话、有人吵架、有人从巷子里走过去。你在这里待久了，才会觉得这座城是活的。</p><h2 id="留下来的那句" tabindex="-1">留下来的那句</h2><p>合上书之后，我想起的不是任何一场打斗，而是那张珠帘——有人掀帘进来，有人在帘外站了一夜雪。</p><p>江湖不是打出来的，是住出来的。</p>',17)])])}const x=t(a,[["render",d]]);export{c as __pageData,x as default};
